#!/bin/bash
# 官方配方单文件重编（RELEASE_ARM_EXYNOS4210_I9100）
# 用法: rebuild_obj.sh <osfmk|bsd> <src.c|src.cpp>
set -ef
GROUP=$1
SRC=$2
X=/mnt/d/Desktop/Git/ios-samsung-i9100/xnu-S2I9100/xnu
EH=$X/BUILD/obj/EXPORT_HDRS
XH=$X/BUILD/obj/EXTERN_HDRS

BASE="-nostdinc -freorder-blocks -fno-builtin -fno-common -fsigned-bitfields -Wno-error=int-conversion -Wno-error=cast-align -Wno-error=implicit-function-declaration -Wno-error=implicit-int -Wno-error=deprecated-declarations -fno-stack-protector -gdwarf-2 -DMACHINE_CONFIG_EXYNOS4210_I9100 --target=armv7-apple-darwin -mthumb -Darm -DARM -D__ARM__ -DPAGE_SIZE_FIXED -fno-strict-aliasing -fno-keep-inline-functions -msoft-float -O1 -DAPPLE -DKERNEL -DKERNEL_PRIVATE -DXNU_KERNEL_PRIVATE -DPRIVATE -D__MACHO__=1 -Dvolatile=__volatile -DBOARD_CONFIG_EXYNOS4210_I9100 -DTARGET_OS_EMBEDDED=1 -include meta_features.h -w -MD"

if [ "$GROUP" = osfmk ]; then
DEFS="-DMACH -DMACH_KERNEL -DMACH_LOAD -DCONFIG_ZLEAKS -DCONFIG_SLEEP -DCONFIG_THREAD_MAX=\"1024\" -DCONFIG_TASK_MAX=\"512\" -DCONFIG_ZONE_MAP_MIN=\"1048576\" -DCONFIG_ZLEAK_ALLOCATION_MAP_NUM=\"8192\" -DCONFIG_ZLEAK_TRACE_MAP_NUM=\"4096\" -DCONFIG_EMBEDDED -DCONFIG_ENFORCE_SIGNED_CODE -DSECURE_KERNEL -DCONFIG_SCHED_TRADITIONAL -DCONFIG_SCHED_PROTO -DCONFIG_SCHED_GRRR -DCONFIG_SCHED_FIXEDPRIORITY -DCONFIG_SCHED_GRRR_CORE -DCONFIG_SCHED_IDLE_IN_PLACE -DCONFIG_MEMORYSTATUS -DCONFIG_JETSAM -DCONFIG_FREEZE -DVM_PRESSURE_EVENTS -DUXPR -DEVENT -DMACH_BSD -DIOKIT -DMACH_PE -DCONFIG_MACF -DCONFIG_AUDIT -DCONFIG_NESTED_PMAP -DMACH_KERNEL_PRIVATE"
INC="-I. -I$X/. -I$EH/. -I$EH/osfmk -I$X/osfmk -I$EH/bsd -I$EH/libkern -I$EH/iokit -I$EH/pexpert -I$EH/libsa -I$EH/security -I$XH -I$X/EXTERNAL_HEADERS -I$X/EXTERNAL_HEADERS/bsd -I$X/osfmk/libsa -I$X/BUILD/obj/RELEASE_ARM_EXYNOS4210_I9100/osfmk/RELEASE"
OUTDIR=$X/BUILD/obj/RELEASE_ARM_EXYNOS4210_I9100/osfmk/RELEASE
elif [ "$GROUP" = bsd ]; then
DEFS="-DNEXT -DTIMEZONE=\"0\" -DPST=\"0\" -DABSOLUTETIME_SCALAR_TYPE -DCONFIG_LCTX -DMACH -DCONFIG_ZLEAKS -DNO_DIRECT_RPC -DIPFIREWALL_FORWARD -DIPFIREWALL_DEFAULT_TO_ACCEPT -DTRAFFIC_MGT -DRANDOM_IP_ID -DTCP_DROP_SYNFIN -DICMP_BANDLIM -DIFNET_INPUT_SANITY_CHK -DPSYNCH -DSECURE_KERNEL -DOLD_SEMWAIT_SIGNAL -DCONFIG_MBUF_JUMBO -DCONFIG_WORKQUEUE -DCONFIG_HFS_STD -DCONFIG_HFS_TRIM -DQUOTA -DNAMEDSTREAMS -DCONFIG_VOLFS -DCONFIG_IMGSRC_ACCESS -DCONFIG_TRIGGERS -DCONFIG_VFS_FUNNEL -DCONFIG_EXT_RESOLVER -DCONFIG_SEARCHFS -DIPSEC -DIPSEC_ESP -DIPV6FIREWALL_DEFAULT_TO_ACCEPT -Dcrypto -Drandomipid -DCONFIG_KN_HASHSIZE=\"20\" -DCONFIG_VNODES=\"750\" -DCONFIG_VNODE_FREE_MIN=\"75\" -DCONFIG_NC_HASH=\"1024\" -DCONFIG_VFS_NAMES=\"2048\" -DCONFIG_MAX_CLUSTERS=\"4\" -DKAUTH_CRED_PRIMES_COUNT=\"3\" -DKAUTH_CRED_PRIMES=\"{5, 17, 97}\" -DCONFIG_MIN_NBUF=\"64\" -DCONFIG_MIN_NIOBUF=\"32\" -DCONFIG_NMBCLUSTERS=\"((1024 * 256) / MCLBYTES)\" -DCONFIG_TCBHASHSIZE=\"128\" -DCONFIG_ICMP_BANDLIM=\"50\" -DCONFIG_AIO_MAX=\"10\" -DCONFIG_AIO_PROCESS_MAX=\"4\" -DCONFIG_AIO_THREAD_COUNT=\"2\" -DCONFIG_THREAD_MAX=\"1024\" -DCONFIG_MAXVIFS=\"2\" -DCONFIG_MFCTBLSIZ=\"16\" -DCONFIG_MSG_BSIZE=\"4096\" -DCONFIG_EMBEDDED -DCONFIG_ENFORCE_SIGNED_CODE -DCONFIG_MEMORYSTATUS -DCONFIG_JETSAM -DCONFIG_FREEZE -DVM_PRESSURE_EVENTS -DCONFIG_APP_PROFILE=\"0\" -DARCH_PRIVATE -DDRIVER_PRIVATE -D_KERNEL_BUILD -DKERNEL_BUILD -DMACH_KERNEL -DBSD_BUILD -DBSD_KERNEL_PRIVATE -DLP64KERN=1 -DLP64_DEBUG=0"
INC="-I. -I$X/. -I$EH/. -I$EH/osfmk -I$EH/bsd -I$EH/libkern -I$EH/iokit -I$EH/pexpert -I$EH/libsa -I$EH/security -I$XH -I$X/EXTERNAL_HEADERS -I$X/EXTERNAL_HEADERS/bsd -I$X/bsd -I$X/osfmk -I$X/osfmk/libsa -I$X/BUILD/obj/RELEASE_ARM_EXYNOS4210_I9100/osfmk/RELEASE"
OUTDIR=$X/BUILD/obj/RELEASE_ARM_EXYNOS4210_I9100/bsd/RELEASE
else
echo "usage: $0 <osfmk|bsd> <src>" >&2; exit 1
fi

cd "$OUTDIR"
eval /usr/bin/clang -c $BASE $DEFS $INC "$SRC" -o "$(basename ${SRC%.*}).o"
